package com.feralenterprises.hoverlite;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Remove only an NPC's terminal combat-level suffix, in display text only. */
final class AutoShorten
{
    private static final Pattern LEVEL_AT_END = Pattern.compile(
        "^(.*?)([\\p{Zs}\\t ]*)\\(level-[0-9]{1,6}\\)[\\p{Zs}\\t\\u200B\\uFEFF]*$",
        Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CHARACTER_CLASS | Pattern.DOTALL);
    private static final Pattern OTHER_LEVEL = Pattern.compile("(?i)\\(level-[0-9]+\\)");
    private AutoShorten() {}

    static String shorten(HoverCategory category, String target)
    {
        if (category != HoverCategory.NPC)
        {
            return target;
        }
        SafeMenuText parsed = SafeMenuText.parse(target);
        if (parsed == null || parsed.hasUnanchoredColor())
        {
            return target;
        }
        Matcher m = LEVEL_AT_END.matcher(parsed.visible);
        if (!m.matches() || m.group(1).trim().isEmpty() || OTHER_LEVEL.matcher(m.group(1)).find())
        {
            return target;
        }
        // No-space NPC suffixes are only verified when the name and level are
        // visibly separated by a recognized RuneLite color-tag boundary.
        if (m.group(2).isEmpty() && !parsed.hasColorBoundaryBefore(m.end(2)))
        {
            return target;
        }
        // Preserve all real NPC-name characters and their existing name markup.
        return parsed.prefix(m.end(1));
    }
}

package com.feralenterprises.hoverlite;

import net.runelite.api.MenuAction;

/** No abbreviations for item-on-target, selected spell, or unknown menu actions. */
final class AutoShortenSafety
{
    private AutoShortenSafety() {}

    static boolean allows(MenuAction type)
    {
        if (type == null) return false;
        switch (type)
        {
            case NPC_FIRST_OPTION:
            case NPC_SECOND_OPTION:
            case NPC_THIRD_OPTION:
            case NPC_FOURTH_OPTION:
            case NPC_FIFTH_OPTION:
            case EXAMINE_NPC:
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
            case EXAMINE_OBJECT:
                return true;
            default:
                return false;
        }
    }
}

package com.feralenterprises.hoverlite;

import java.util.Locale;
import java.util.regex.Pattern;

/** Verified, category-aware action cleanup. Directions and modifiers are sacred. */
final class CoreAction
{
    private static final Pattern BASIC_TREE = Pattern.compile(
        "^(Oak|Willow|Maple|Yew|Magic|Teak|Mahogany|Redwood) tree$|^Tree$|^Dead tree$|^Spirit tree$",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern BUSH = Pattern.compile(
        "^[\\p{L}][\\p{L} '-]* bush$", Pattern.CASE_INSENSITIVE);
    private CoreAction() {}

    static String shorten(HoverCategory category, String action, String target)
    {
        if (category == null || action == null || action.isEmpty() || action.indexOf('<') >= 0
            || action.indexOf('>') >= 0)
        {
            return action;
        }
        SafeMenuText parsed = SafeMenuText.parse(target);
        if (parsed == null || parsed.hasUnanchoredColor())
        {
            return action;
        }
        final String name = parsed.visible.trim();
        String replacement = null;
        if (category == HoverCategory.NPC && action.equalsIgnoreCase("Talk-to"))
        {
            replacement = "Talk";
        }
        else if (category == HoverCategory.GAME_OBJECT)
        {
            if (action.equalsIgnoreCase("Chop down") && BASIC_TREE.matcher(name).matches())
            {
                replacement = "Chop";
            }
            else if (action.equalsIgnoreCase("Pray-at") && name.equalsIgnoreCase("Altar"))
            {
                replacement = "Pray";
            }
            else if (action.equalsIgnoreCase("Pick-from") && BUSH.matcher(name).matches())
            {
                replacement = "Pick";
            }
            else if (action.equalsIgnoreCase("Pick-spine") && name.equalsIgnoreCase("Cactus"))
            {
                replacement = "Pick";
            }
        }
        if (replacement == null)
        {
            return action;
        }
        return Character.isLowerCase(action.charAt(0)) ? replacement.toLowerCase(Locale.ROOT) : replacement;
    }
}

package com.feralenterprises.hoverlite;

import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;

/** Categories are inferred only from RuneLite's menu entries. Never modify an entry. */
public enum HoverCategory
{
    NPC, INVENTORY_ITEM, GAME_OBJECT, GROUND_ITEM, PLAYER, INTERFACE, OTHER;

    static HoverCategory from(MenuEntry entry)
    {
        MenuAction type = entry.getType();
        if (type == null)
        {
            return OTHER;
        }
        switch (type)
        {
            case ITEM_USE_ON_NPC:
            case WIDGET_TARGET_ON_NPC:
            case NPC_FIRST_OPTION:
            case NPC_SECOND_OPTION:
            case NPC_THIRD_OPTION:
            case NPC_FOURTH_OPTION:
            case NPC_FIFTH_OPTION:
            case EXAMINE_NPC:
                return NPC;

            case ITEM_USE_ON_GAME_OBJECT:
            case WIDGET_TARGET_ON_GAME_OBJECT:
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
            case EXAMINE_OBJECT:
                return GAME_OBJECT;

            case ITEM_USE_ON_GROUND_ITEM:
            case WIDGET_TARGET_ON_GROUND_ITEM:
            case GROUND_ITEM_FIRST_OPTION:
            case GROUND_ITEM_SECOND_OPTION:
            case GROUND_ITEM_THIRD_OPTION:
            case GROUND_ITEM_FOURTH_OPTION:
            case GROUND_ITEM_FIFTH_OPTION:
            case EXAMINE_ITEM_GROUND:
                return GROUND_ITEM;

            case ITEM_USE_ON_PLAYER:
            case WIDGET_TARGET_ON_PLAYER:
            case PLAYER_FIRST_OPTION:
            case PLAYER_SECOND_OPTION:
            case PLAYER_THIRD_OPTION:
            case PLAYER_FOURTH_OPTION:
            case PLAYER_FIFTH_OPTION:
            case PLAYER_SIXTH_OPTION:
            case PLAYER_SEVENTH_OPTION:
            case PLAYER_EIGHTH_OPTION:
            case RUNELITE_PLAYER:
                return PLAYER;

            case ITEM_USE_ON_ITEM:
            case WIDGET_USE_ON_ITEM:
            case ITEM_FIRST_OPTION:
            case ITEM_SECOND_OPTION:
            case ITEM_THIRD_OPTION:
            case ITEM_FOURTH_OPTION:
            case ITEM_FIFTH_OPTION:
            case ITEM_USE:
            case EXAMINE_ITEM:
                return INVENTORY_ITEM;

            case WIDGET_TYPE_1:
            case WIDGET_TARGET:
            case WIDGET_CLOSE:
            case WIDGET_TYPE_4:
            case WIDGET_TYPE_5:
            case WIDGET_CONTINUE:
            case WIDGET_FIRST_OPTION:
            case WIDGET_SECOND_OPTION:
            case WIDGET_THIRD_OPTION:
            case WIDGET_FOURTH_OPTION:
            case WIDGET_FIFTH_OPTION:
            case WIDGET_TARGET_ON_WIDGET:
            case CC_OP:
            case RUNELITE_WIDGET:
            {
                // Modern RuneLite uses CC_OP on items too. Preserve inventory behavior
                // when the clicked widget is in the inventory or side-inventory group.
                final int group = WidgetUtil.componentToInterface(entry.getParam1());
                if (group == InterfaceID.INVENTORY || group == InterfaceID.BANKSIDE
                    || group == InterfaceID.GE_OFFERS_SIDE || group == InterfaceID.SHOPSIDE
                    || group == InterfaceID.TRADESIDE || group == InterfaceID.BANK_DEPOSITBOX
                    || group == InterfaceID.EQUIPMENT_SIDE)
                {
                    return INVENTORY_ITEM;
                }
                return INTERFACE;
            }

            default:
                return OTHER;
        }
    }
}

package com.feralenterprises.hoverlite;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("hoverlite")
public interface HoverLiteConfig extends Config
{
    @ConfigSection(name = "Auto Shorten", description = "Automatic ACTION + name cleaning", position = 0)
    String AUTO = "auto";

    @ConfigSection(name = "Fallback display", description = "Used when Auto Shorten is turned off, or for other categories", position = 1)
    String DISPLAY = "display";

    @ConfigSection(name = "Behavior", description = "Tooltip safety and convenience options", position = 2)
    String BEHAVIOR = "behavior";

    @ConfigItem(keyName = "autoShortenEnabled", name = "Enable Auto Shorten", description = "ON by default. Automatically simplify NPC and world object tooltips, even if older settings were saved. Turn off to use fallback modes below.", position = 0, section = AUTO)
    default boolean autoShortenEnabled() { return true; }

    @ConfigItem(keyName = "npcMode", name = "NPCs", description = "Fallback mode when Auto Shorten is disabled", position = 0, section = DISPLAY)
    default HoverMode npcMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "inventoryMode", name = "Inventory / item panels", description = "Keep item names visible while hovering inventory or bank items", position = 1, section = DISPLAY)
    default HoverMode inventoryMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "objectMode", name = "World objects", description = "Fallback mode when Auto Shorten is disabled", position = 2, section = DISPLAY)
    default HoverMode objectMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "groundMode", name = "Ground items", description = "Items lying on the ground", position = 3, section = DISPLAY)
    default HoverMode groundMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "playerMode", name = "Players", description = "Actions on other players", position = 4, section = DISPLAY)
    default HoverMode playerMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "interfaceMode", name = "Interface buttons", description = "Non-item widgets such as buttons and tabs", position = 5, section = DISPLAY)
    default HoverMode interfaceMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "otherMode", name = "Other actions", description = "Unclassified game actions", position = 6, section = DISPLAY)
    default HoverMode otherMode() { return HoverMode.FULL; }

    @ConfigItem(keyName = "hideTrivial", name = "Ignore trivial actions", description = "Don't show hover text for Walk here, Cancel, Continue, or sliding puzzle Move", position = 0, section = BEHAVIOR)
    default boolean hideTrivial() { return true; }

    @ConfigItem(keyName = "respectNative", name = "Respect built-in tooltips", description = "Avoid drawing on top of tooltips generated by the game itself", position = 1, section = BEHAVIOR)
    default boolean respectNative() { return true; }

}

package com.feralenterprises.hoverlite;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/** A safe replacement for RuneLite's built-in Mouse Tooltips overlay. */
public class HoverLiteOverlay extends Overlay
{
    private final Client client;
    private final TooltipManager tooltips;
    private final HoverLiteConfig config;

    @Inject
    HoverLiteOverlay(Client client, TooltipManager tooltips, HoverLiteConfig config)
    {
        this.client = client;
        this.tooltips = tooltips;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        // Match RuneLite Mouse Tooltips on full-screen interfaces.
        drawAfterInterface(InterfaceID.TOPLEVEL_DISPLAY);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.isMenuOpen())
        {
            return null;
        }
        MenuEntry[] entries = client.getMenuEntries();
        if (entries == null || entries.length == 0)
        {
            return null;
        }
        // The last entry is RuneLite's current default left-click action.
        MenuEntry entry = entries[entries.length - 1];
        if (entry == null)
        {
            return null;
        }
        MenuAction type = entry.getType();
        if (type == MenuAction.RUNELITE_OVERLAY || type == MenuAction.RUNELITE_OVERLAY_CONFIG
            || type == MenuAction.CC_OP_LOW_PRIORITY || type == MenuAction.RUNELITE_LOW_PRIORITY)
        {
            return null;
        }
        String action = entry.getOption();
        String target = entry.getTarget();
        if (action == null || action.isEmpty())
        {
            return null;
        }
        if (config.hideTrivial())
        {
            switch (action)
            {
                case "Walk here":
                case "Cancel":
                case "Continue":
                case "Set heading":
                    return null;
                case "Move":
                    if (target != null && target.contains("Sliding piece"))
                    {
                        return null;
                    }
                    break;
                default:
                    break;
            }
        }
        if (config.respectNative())
        {
            if (client.getVarcIntValue(VarClientID.TOOLTIP_TIME) > client.getGameCycle()
                || client.getVarcIntValue(VarClientID.TOOLTIP_BUILT) == 1)
            {
                return null;
            }
        }
        HoverCategory category = HoverCategory.from(entry);
        HoverMode mode = effectiveMode(category, type);
        String value = HoverText.format(mode, category, action, target);
        if (value != null)
        {
            // Only auto mode can collapse distinct original labels into the
            // same shortened label. On a crowded tile, preserve the original.
            if (mode == HoverMode.SMART_SHORTEN)
            {
                final String original = HoverText.format(HoverMode.FULL, category, action, target);
                for (int i = 0; i < entries.length - 1; i++)
                {
                    final MenuEntry other = entries[i];
                    if (other == null || other.getOption() == null)
                    {
                        continue;
                    }
                    final HoverCategory otherCategory = HoverCategory.from(other);
                    final String otherOriginal = HoverText.format(HoverMode.FULL, otherCategory,
                        other.getOption(), other.getTarget());
                    final String otherVisible = HoverText.format(effectiveMode(otherCategory, other.getType()), otherCategory,
                        other.getOption(), other.getTarget());
                    if (TooltipCollisionGuard.isAmbiguous(original, value, otherOriginal, otherVisible))
                    {
                        // Owner policy: do not reintroduce NPC combat levels
                        // solely because another NPC has the same name.
                        if (TooltipCollisionGuard.onlyNpcCombatLevelsDiffer(category, action, target,
                            otherCategory, other.getOption(), other.getTarget()))
                        {
                            continue;
                        }
                        // Preserve the ORIGINAL action/name for real collisions,
                        // but honor NPC level removal whenever its markup is valid.
                        final String fallbackTarget = category == HoverCategory.NPC
                            ? AutoShorten.shorten(category, target) : target;
                        value = HoverText.format(HoverMode.FULL, category, action, fallbackTarget);
                        break;
                    }
                }
            }
            tooltips.addFront(new Tooltip(value));
        }
        return null;
    }

    private HoverMode effectiveMode(HoverCategory category, MenuAction actionType)
    {
        final HoverMode configured = HoverModePolicy.resolve(category, modeFor(category), config.autoShortenEnabled());
        return configured == HoverMode.SMART_SHORTEN && !AutoShortenSafety.allows(actionType)
            ? HoverMode.FULL : configured;
    }

    private HoverMode modeFor(HoverCategory category)
    {
        switch (category)
        {
            case NPC: return config.npcMode();
            case INVENTORY_ITEM: return config.inventoryMode();
            case GAME_OBJECT: return config.objectMode();
            case GROUND_ITEM: return config.groundMode();
            case PLAYER: return config.playerMode();
            case INTERFACE: return config.interfaceMode();
            default: return config.otherMode();
        }
    }
}

package com.feralenterprises.hoverlite;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "HoverLite",
    description = "Auto-shorten NPC and object hover text while preserving useful inventory text",
    tags = {"mouse", "tooltips", "hover", "accessibility", "customization"}
)
public class HoverLitePlugin extends Plugin
{
    @Inject private OverlayManager overlayManager;
    @Inject private HoverLiteOverlay overlay;

    @Provides
    HoverLiteConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(HoverLiteConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
    }
}

package com.feralenterprises.hoverlite;

/** What HoverLite shows for an interaction category. */
public enum HoverMode
{
    FULL("Full action + target"),
    SMART_SHORTEN("Auto Shorten"),
    ACTION_ONLY("Action only"),
    INDICATOR("Indicator only"),
    HIDDEN("Hidden");

    private final String label;

    HoverMode(String label)
    {
        this.label = label;
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.feralenterprises.hoverlite;

/** Global Auto Shorten defaults ON for NPCs/objects, even with persisted v0.1.x display modes. */
final class HoverModePolicy
{
    private HoverModePolicy() {}

    static HoverMode resolve(HoverCategory category, HoverMode configured, boolean autoEnabled)
    {
        if (autoEnabled && (category == HoverCategory.NPC || category == HoverCategory.GAME_OBJECT))
        {
            return HoverMode.SMART_SHORTEN;
        }
        return configured;
    }
}

package com.feralenterprises.hoverlite;

/** Pure formatting logic: no game actions, menu modification, or state writes. */
final class HoverText
{
    private HoverText() {}

    // Kept for compatibility with the original pure formatting tests/callers.
    static String format(HoverMode mode, String action, String target)
    {
        return format(mode, HoverCategory.OTHER, action, target);
    }

    static String format(HoverMode mode, HoverCategory category, String action, String target)
    {
        if (mode == null || mode == HoverMode.HIDDEN || action == null || action.trim().isEmpty())
        {
            return null;
        }
        if (mode == HoverMode.INDICATOR)
        {
            return "<col=65eeb0>●</col>";
        }
        if (mode == HoverMode.ACTION_ONLY)
        {
            return action;
        }
        if (mode == HoverMode.SMART_SHORTEN)
        {
            // Keep original RuneLite menu entries intact; only presentation changes.
            // Normalize the core action independently of the target's name.
            final String originalAction = action;
            action = CoreAction.shorten(category, originalAction, target);
            target = TargetShorten.shorten(category, originalAction,
                AutoShorten.shorten(category, target));
        }
        return target == null || target.isEmpty() ? action : action + " " + target;
    }
}

package com.feralenterprises.hoverlite;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Parse only RuneLite's simple color markup. Never interpret arbitrary tags or
 * change the underlying MenuEntry. Unknown markup is intentionally unsupported.
 *
 * Unlike a regex anchored to one color layout, this retains the location of
 * every visible character, allowing a suffix to be removed even when a color
 * tag sits between a name and its combat level.
 */
final class SafeMenuText
{
    private static final Pattern OPEN = Pattern.compile("(?i)<col=[0-9a-f]{1,8}>");
    private static final Pattern CLOSE = Pattern.compile("(?i)</col>");
    // Permit invisible Unicode only AFTER a terminal combat level, before optional
    // whitespace/closing color tags. Embedded controls still fail closed.
    private static final Pattern LEVEL_BEFORE_TRAILING_INVISIBLE = Pattern.compile(
        "(?i).*\\(level-[0-9]{1,6}\\)[\\p{Zs}\\t\\u200B\\uFEFF]*$");
    private static final Pattern SAFE_TAIL = Pattern.compile(
        "(?i)(?:[\\p{Zs}\\t\\u200B\\uFEFF]|</col>)*");
    private static final Pattern COLOR_BOUNDARY = Pattern.compile(
        "(?i)(?:<col=[0-9a-f]{1,8}>|</col>)+");

    final String raw;
    final String visible;
    private final int[] rawEnds;
    private final String leadingColor;
    private final boolean simpleColor;
    private final boolean endsClosed;

    private SafeMenuText(String raw, String visible, int[] rawEnds,
                         String leadingColor, boolean simpleColor, boolean endsClosed)
    {
        this.raw = raw;
        this.visible = visible;
        this.rawEnds = rawEnds;
        this.leadingColor = leadingColor;
        this.simpleColor = simpleColor;
        this.endsClosed = endsClosed;
    }

    static SafeMenuText parse(String raw)
    {
        if (raw == null || raw.isEmpty() || raw.length() > 2048)
        {
            return null;
        }
        StringBuilder plain = new StringBuilder();
        List<Integer> ends = new ArrayList<>();
        String firstColor = null;
        boolean simpleColor = true;
        boolean hasVisible = false;
        boolean hasColor = false;
        int changedColorAtVisibleIndex = -1;
        int lastTagEnd = -1;
        boolean lastTagWasClose = false;
        for (int i = 0; i < raw.length();)
        {
            final char c = raw.charAt(i);
            if (Character.isISOControl(c) || c == '>')
            {
                return null;
            }
            if (c == '\u200b' || c == '\ufeff')
            {
                // A zero-width code point inside an NPC name is never silently
                // normalized. Only documented suffix-tail artifacts are allowed.
                if (!LEVEL_BEFORE_TRAILING_INVISIBLE.matcher(plain).matches()
                    || !SAFE_TAIL.matcher(raw.substring(i)).matches())
                {
                    return null;
                }
            }
            if (c == '<')
            {
                final int close = raw.indexOf('>', i + 1);
                if (close < 0)
                {
                    return null;
                }
                final String tag = raw.substring(i, close + 1);
                if (OPEN.matcher(tag).matches())
                {
                    if (hasColor && !hasVisible)
                    {
                        simpleColor = false;
                    }
                    if (hasVisible)
                    {
                        changedColorAtVisibleIndex = plain.length();
                    }
                    if (!hasColor && !hasVisible)
                    {
                        firstColor = tag;
                    }
                    hasColor = true;
                    lastTagWasClose = false;
                }
                else if (CLOSE.matcher(tag).matches())
                {
                    lastTagWasClose = true;
                }
                else
                {
                    return null;
                }
                lastTagEnd = close + 1;
                i = close + 1;
                continue;
            }
            plain.append(c);
            ends.add(i + 1);
            hasVisible = true;
            i++;
        }
        int[] offsets = new int[ends.size()];
        for (int i = 0; i < ends.size(); i++)
        {
            offsets[i] = ends.get(i);
        }
        // A color tag after the last visible character is harmless trailing
        // markup. A change within the visible target is meaningful, so never
        // rewrite that target's name without knowing the span's intent.
        if (changedColorAtVisibleIndex >= 0 && changedColorAtVisibleIndex < plain.length())
        {
            simpleColor = false;
        }
        return new SafeMenuText(raw, plain.toString(), offsets, firstColor,
            simpleColor, lastTagWasClose && lastTagEnd == raw.length());
    }

    /** A missing visible space is safe only when a real color tag separates spans. */
    boolean hasColorBoundaryBefore(int visibleIndex)
    {
        if (visibleIndex <= 0 || visibleIndex >= rawEnds.length)
        {
            return false;
        }
        final int gapStart = rawEnds[visibleIndex - 1];
        final int gapEnd = rawEnds[visibleIndex] - 1;
        return gapEnd > gapStart && COLOR_BOUNDARY.matcher(raw.substring(gapStart, gapEnd)).matches();
    }

    /** A floating color tag without a name-color opener is unsafe to abbreviate. */
    boolean hasUnanchoredColor()
    {
        return raw.toLowerCase(Locale.ROOT).contains("<col=") && leadingColor == null;
    }

    /** Preserve the exact original name markup, stopping before removable suffixes. */
    String prefix(int visibleCharacters)
    {
        if (visibleCharacters <= 0 || visibleCharacters > rawEnds.length)
        {
            return raw;
        }
        String shortened = raw.substring(0, rawEnds[visibleCharacters - 1]);
        // Keep a name's explicit closing color tag if one immediately follows it.
        final String rest = raw.substring(rawEnds[visibleCharacters - 1]);
        if (rest.regionMatches(true, 0, "</col>", 0, 6))
        {
            shortened += rest.substring(0, 6);
        }
        else if (simpleColor && endsClosed && leadingColor != null
            && !shortened.toLowerCase(Locale.ROOT).endsWith("</col>"))
        {
            shortened += "</col>";
        }
        return shortened;
    }

    /** Only replace whole names when an initial, uniform name color is known. */
    String replaceName(String replacement)
    {
        if (!simpleColor || replacement == null || replacement.trim().isEmpty()
            || replacement.indexOf('<') >= 0 || replacement.indexOf('>') >= 0)
        {
            return raw;
        }
        return (leadingColor == null ? "" : leadingColor) + replacement
            + (endsClosed && leadingColor != null ? "</col>" : "");
    }
}

package com.feralenterprises.hoverlite;

import java.util.regex.Pattern;

/** Display-only whole-name cleanup for exact owner-verified interactions. */
final class TargetShorten
{
    private static final Pattern TREE = Pattern.compile(
        "^(Oak|Willow|Maple|Yew|Magic|Teak|Mahogany|Redwood) tree$", Pattern.CASE_INSENSITIVE);
    private TargetShorten() {}

    static String shorten(HoverCategory category, String action, String target)
    {
        if (category == null || action == null)
        {
            return target;
        }
        final SafeMenuText parsed = SafeMenuText.parse(target);
        if (parsed == null || parsed.hasUnanchoredColor())
        {
            return target;
        }
        final String name = parsed.visible.trim();
        String replacement = null;
        if (category == HoverCategory.GAME_OBJECT)
        {
            if (action.equalsIgnoreCase("Chop down") && TREE.matcher(name).matches())
            {
                replacement = name.substring(0, name.length() - " tree".length());
            }
            else if (action.equalsIgnoreCase("Pick") && name.equalsIgnoreCase("Limpwurt plant"))
            {
                replacement = "Limpwurt";
            }
            else if (action.equalsIgnoreCase("Open") && name.equalsIgnoreCase("Seed vault"))
            {
                replacement = "Vault";
            }
            else if (action.equalsIgnoreCase("Mine") && name.equalsIgnoreCase("Iron rocks"))
            {
                replacement = "Iron";
            }
            else if (action.equalsIgnoreCase("Mine") && name.equalsIgnoreCase("Coal rocks"))
            {
                replacement = "Coal";
            }
        }
        else if (category == HoverCategory.NPC && action.equalsIgnoreCase("Exchange")
            && name.equalsIgnoreCase("Tool Leprechaun"))
        {
            replacement = "Leprechaun";
        }
        return replacement == null ? target : parsed.replaceName(replacement);
    }
}

package com.feralenterprises.hoverlite;

import java.util.regex.Pattern;

/**
 * Prevent the auto mode from giving two distinct actions the same visible label
 * on the current interaction menu. Identical originals are not a collision.
 */
final class TooltipCollisionGuard
{
    private static final Pattern TAGS = Pattern.compile("<[^<>]*>");

    private TooltipCollisionGuard() {}

    static boolean isAmbiguous(String original, String shortened, String competingOriginal,
                               String competingShortened)
    {
        if (shortened == null || competingShortened == null || original == null || competingOriginal == null)
        {
            return false;
        }
        final String displayed = visible(shortened);
        return displayed.equalsIgnoreCase(visible(competingShortened))
            && !visible(original).equalsIgnoreCase(visible(competingOriginal));
    }

    /**
     * NPC combat levels are optional display-only metadata in Auto Shorten.
     * Two menu entries whose only distinguishing text is a verified level suffix
     * must not cause the overlay to put the level back on screen.
     *
     * This is NOT a general collision bypass. Different actions or names still
     * require a fallback, and malformed level layouts remain untouched.
     */
    static boolean onlyNpcCombatLevelsDiffer(HoverCategory firstCategory, String firstAction,
            String firstTarget, HoverCategory secondCategory, String secondAction, String secondTarget)
    {
        if (firstCategory != HoverCategory.NPC || secondCategory != HoverCategory.NPC
            || firstAction == null || secondAction == null || !firstAction.equals(secondAction)
            || firstTarget == null || secondTarget == null)
        {
            return false;
        }
        final String firstShort = AutoShorten.shorten(HoverCategory.NPC, firstTarget);
        final String secondShort = AutoShorten.shorten(HoverCategory.NPC, secondTarget);
        // Both inputs must actually contain a well-formed removable level.
        return !visible(firstTarget).equalsIgnoreCase(visible(secondTarget))
            && !visible(firstTarget).equalsIgnoreCase(visible(firstShort))
            && !visible(secondTarget).equalsIgnoreCase(visible(secondShort))
            && visible(firstShort).equalsIgnoreCase(visible(secondShort));
    }

    private static String visible(String input)
    {
        return TAGS.matcher(input).replaceAll("").trim();
    }
}

